const input = $json ?? {};
const incoming = input.query && typeof input.query === 'object'
  ? input.query
  : (input.body && typeof input.body === 'object' ? input.body : input);
const requestedSource = String(incoming.source ?? '').trim().toLowerCase();
const sources = requestedSource ? [requestedSource] : ['linkedin', 'infojobs'];
if (sources.some(source => !['linkedin', 'infojobs'].includes(source))) {
  throw new Error('source debe ser linkedin o infojobs');
}
const baseUrl = String($env.PLAYWRIGHT_BASE_URL || 'http://playwright:3000').replace(/\/+$/, '');
const textParam = value => Array.isArray(value) ? value.map(String).map(value => value.trim()).filter(Boolean).join(',') : String(value ?? '').trim();
const positiveInteger = (value, minimum = 1) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= minimum ? String(parsed) : null;
};
const location = textParam(incoming.location);
const keywords = textParam(incoming.keywords);
const requestedAt = new Date().toISOString();
return sources.map(source => {
  const params = new URLSearchParams();
  if (location) params.set('location', location);
  if (keywords) params.set('keywords', keywords);
  for (const [name, value] of [
    ['termsPerQuery', positiveInteger(incoming.termsPerQuery)],
    ['maxJobsPerSearch', positiveInteger(incoming.maxJobsPerSearch)],
    ['maxScrollSteps', positiveInteger(incoming.maxScrollSteps, 0)],
    ['gotoTimeout', positiveInteger(incoming.gotoTimeout)],
    ['selectorTimeout', positiveInteger(incoming.selectorTimeout)],
  ]) {
    if (value !== null) params.set(name, value);
  }
  const query = params.toString();
  return {
    json: {
      source,
      endpoint: `${baseUrl}/${source}`,
      targetUrl: `${baseUrl}/${source}${query ? `?${query}` : ''}`,
      requestedAt,
    },
  };
});

const text = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const cleanTitle = value => {
  const title = text(value);
  const half = title.length / 2;
  return Number.isInteger(half) && title.slice(0, half) === title.slice(half) ? title.slice(0, half).trim() : title;
};
const normalizeLink = (value, source) => {
  const raw = text(value);
  if (!raw) return null;
  try {
    const url = new URL(raw, source === 'infojobs' ? 'https://www.infojobs.net' : 'https://www.linkedin.com');
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    url.search = '';
    url.hash = '';
    url.pathname = url.pathname.replace(/\/+$/, '') || '/';
    return url.href;
  } catch {
    return raw;
  }
};
const extractId = (link, source) => {
  if (!link) return null;
  if (source === 'infojobs') {
    return link.match(/[?&](?:id|offerId|offer_id)=([A-Za-z0-9_-]+)/i)?.[1]
      || link.match(/\/of-([A-Za-z0-9_-]+)(?:[/?#]|$)/i)?.[1]
      || link.match(/(?:^|[/-])(\d{5,})(?:[/?#-]|$)/)?.[1]
      || null;
  }
  return link.match(/(?:-|%2D|\/view\/)(\d+)(?:[/?]|$)/i)?.[1] || null;
};
const arrays = ['skills', 'requirements', 'education', 'languages', 'experience', 'detectedKeywords'];
const expand = value => {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.jobs)) return value.jobs;
  if (value && Array.isArray(value.data)) return value.data;
  return value && typeof value === 'object' ? [value] : [];
};
const now = new Date().toISOString();
const output = [];
for (const item of $input.all()) {
  for (const raw of expand(item.json)) {
    if (!raw || typeof raw !== 'object') continue;
    const link = normalizeLink(raw.link, raw.source === 'infojobs' || /infojobs/i.test(raw.link ?? '') ? 'infojobs' : 'linkedin');
    const source = text(raw.source).toLowerCase() || (link && /infojobs/i.test(link) ? 'infojobs' : 'linkedin');
    if (!['linkedin', 'infojobs'].includes(source)) continue;
    const title = cleanTitle(raw.title);
    if (!title) continue;
    const id = text(raw.id) || extractId(link, source);
    const company = text(raw.company) || null;
    const location = text(raw.location) || null;
    const fallback = [company, title, location].map(text).join('|').toLocaleLowerCase();
    const identity = id ? `id:${id}` : (link ? `url:${link}` : `fallback:${fallback}`);
    const job = {
      ...raw,
      id: id || null,
      title,
      company,
      location,
      link,
      source,
      scrapedAt: raw.scrapedAt || now,
      item_key: `playwright:${source}:${identity}`,
      dedupe_source: `playwright_${source}`,
    };
    for (const field of arrays) {
      job[field] = Array.isArray(job[field]) ? [...new Set(job[field].map(text).filter(Boolean))] : [];
    }
    job.payload_json = JSON.stringify({ ...job });
    output.push({ json: job });
  }
}
return output.length ? output : [{ json: { __noJobs: true, item_key: '', dedupe_source: '', title: '', payload_json: '{}' } }];

const input = $input.all();
const jobs = input.filter(item => item.json.is_empty !== true && item.json.inserted === true).map(item => {
  const payload = item.json.payload && typeof item.json.payload === 'object' ? item.json.payload : {};
  return {
    ...payload,
    historyUpdatedBy: 'playwright-service',
    preparedAt: new Date().toISOString(),
    status: payload.status || 'new',
  };
});
return [{
  json: {
    ok: true,
    generatedAt: new Date().toISOString(),
    scrapedCount: input.filter(item => item.json.is_empty !== true).length,
    newCount: jobs.length,
    sources: [...new Set(jobs.map(job => job.source).filter(Boolean))],
    jobs,
  },
}];
